import turtle
turtle.Screen().bgcolor("pink")
sc=turtle.Screen()
#Rectangle
pointer=turtle.Turtle()
pointer.fillcolor("sky blue")
pointer.begin_fill()
pointer.forward(200)
pointer.left(90)
pointer.forward(100)
pointer.left(90)
pointer.forward(200)
pointer.left(90)
pointer.forward(100)
pointer.end_fill()
#Star
board=turtle.Turtle()
board.forward(100)
board.left(120)
board.forward(100)
board.left(120)
board.forward(100)
board.penup()
board.right(150)
board.forward(50)
board.pendown()
board.right(90)
board.forward(100)
board.right(120)
board.forward(100)
board.right(120)
board.forward(100)
board.right(120)
board.forward(100)
#Square
square=turtle.Turtle()
square.fillcolor("purple")
square.begin_fill()
square.back(200)
square.left(90)
square.back(200)
square.left(90)
square.back(200)
square.left(90)
square.back(200)
square.right(90)
square.end_fill()
#Pentagon
shape=turtle.Turtle()
shape.fillcolor("light green")
shape.begin_fill()
shape.back(200)
shape.right(90)
shape.back(100)
shape.right(70)
shape.back(102)
shape.right(40)
shape.back(105)
shape.end_fill()
turtle.done()